// Dashboard defines model for Dashboard.
type Dashboard struct {
	// ActiveUsers 窗口内发起过任务（含定时简报）的用户数
	ActiveUsers struct {
		D1  int `json:"d1"`
		D30 int `json:"d30"`
		D7  int `json:"d7"`
	} `json:"activeUsers"`
	Cost struct {
		// AvgReportCostCny 近 30 天已完成报告的平均成本（门槛 B 要求 ≤ ¥3）
		AvgReportCostCny *float64 `json:"avgReportCostCny"`
		Last30dCny       float64  `json:"last30dCny"`
		Last7dCny        float64  `json:"last7dCny"`
		TodayCny         float64  `json:"todayCny"`
	} `json:"cost"`

	// Daily 近 14 天
	Daily            []DailyPoint `json:"daily"`
	ReportsThisMonth int          `json:"reportsThisMonth"`

	// Satisfaction 报告满意度 = satisfied ÷ (satisfied + unsatisfied)，按报告创建日落窗口；评分率 = 已评 ÷ completed。
	// 门槛 B 要求满意度 ≥ 70%，评分率低于 25% 时结论无效。
	Satisfaction Satisfaction `json:"satisfaction"`

	// Shares 近 7 天新建的分享链接及其累计访问 / 点击
	Shares     *ShareStats `json:"shares,omitempty"`
	TasksToday []TaskCount `json:"tasksToday"`
	Users      struct {
		Disabled int `json:"disabled"`
		New7d    int `json:"new7d"`
		NewToday int `json:"newToday"`
		Total    int `json:"total"`
	} `json:"users"`
}

